@Composable
fun tr(key: String): String {
    val lang = LocalLanguage.current
    return trStr(if (lang == "auto") "es" else lang, key)
}

fun trStr(lang: String, key: String): String {
    val cleanLang = lang.lowercase().trim()
    val effectiveLang = if (cleanLang.startsWith("pt")) "pt" else if (cleanLang.startsWith("en")) "en" else "es"
    val isEs = effectiveLang == "es"
    if (isEs) {
        return translations["es"]?.get(key) ?: key
    }
    
    val direct = translations[effectiveLang]?.get(key)
    if (direct != null) return direct
    
    val dynamic = DynamicTranslations.get(effectiveLang, key)
    if (dynamic != null) return dynamic

    // --- REPOSITORY LOOKUP (PORTUGUÊS EM MANUTENÇÃO) ---
    val itemByName = WildRiftRepository.items.find { it.name.equals(key, ignoreCase = true) }
    if (itemByName != null && itemByName.namePt.isNotBlank()) return itemByName.namePt
    
    val itemByStats = WildRiftRepository.items.find { it.stats.equals(key, ignoreCase = true) }
    if (itemByStats != null && itemByStats.statsPt.isNotBlank()) return itemByStats.statsPt
    
    val itemByPassive = WildRiftRepository.items.find { it.passive.equals(key, ignoreCase = true) }
    if (itemByPassive != null && itemByPassive.passivePt.isNotBlank()) return itemByPassive.passivePt
    
    val champByName = WildRiftRepository.champions.find { it.name.equals(key, ignoreCase = true) }
    if (champByName != null && champByName.namePt.isNotBlank()) return champByName.namePt
    
    val runeByName = WildRiftRepository.runes.find { it.name.equals(key, ignoreCase = true) }
    if (runeByName != null && runeByName.namePt.isNotBlank()) return runeByName.namePt
    
    val spellByName = WildRiftRepository.summonerSpells.find { it.name.equals(key, ignoreCase = true) }
    if (spellByName != null && spellByName.namePt.isNotBlank()) return spellByName.namePt

    var replaced = key
    if (effectiveLang == "pt") {
        replaced = replaced.replace("Daño Físico", "Dano Físico", ignoreCase = true)
        replaced = replaced.replace("Daño Mágico", "Dano Mágico", ignoreCase = true)
        replaced = replaced.replace("Defensa", "Defesa", ignoreCase = true)
        replaced = replaced.replace("Magia", "Magia", ignoreCase = true)
        replaced = replaced.replace("Botas", "Botas", ignoreCase = true)
        replaced = replaced.replace("Encantamientos", "Encantamentos", ignoreCase = true)
        replaced = replaced.replace("Parche", "Patch", ignoreCase = true)
        replaced = replaced.replace("Vida Máxima", "Vida Máxima", ignoreCase = true)
        replaced = replaced.replace("Daño de Ataque", "Dano de Ataque", ignoreCase = true)
        replaced = replaced.replace("Poder de Habilidad", "Poder de Habilidade", ignoreCase = true)
        replaced = replaced.replace("Velocidad de Ataque", "Velocidade de Ataque", ignoreCase = true)
        replaced = replaced.replace("Velocidad de Movimiento", "Velocidade de Movimento", ignoreCase = true)
        replaced = replaced.replace("Aceleración de Habilidad", "Aceleração de Habilidade", ignoreCase = true)
        replaced = replaced.replace("Probabilidad de Crítico", "Chance de Crítico", ignoreCase = true)
        replaced = replaced.replace("Daño Crítico", "Dano Crítico", ignoreCase = true)
        replaced = replaced.replace("Penetración de Armadura", "Penetração de Armadura", ignoreCase = true)
        replaced = replaced.replace("Penetración Mágica", "Penetração Mágica", ignoreCase = true)
        replaced = replaced.replace("Resistencia Mágica", "Resistência Mágica", ignoreCase = true)
        replaced = replaced.replace("Armadura", "Armadura", ignoreCase = true)
        replaced = replaced.replace("Robo de Vida", "Roubo de Vida", ignoreCase = true)
        replaced = replaced.replace("Omnivampirismo", "Omnivamp", ignoreCase = true)
        replaced = replaced.replace("Vampirismo", "Vamp", ignoreCase = true)
        replaced = replaced.replace("Daño Verdadero", "Dano Verdadeiro", ignoreCase = true)
        replaced = replaced.replace("Curación", "Cura", ignoreCase = true)
        replaced = replaced.replace("Escudo", "Escudo", ignoreCase = true)
        replaced = replaced.replace("Enfriamiento", "Tempo de Recarga", ignoreCase = true)
        replaced = replaced.replace("Pasiva", "Passiva", ignoreCase = true)
        replaced = replaced.replace("Habilidad", "Habilidade", ignoreCase = true)
        replaced = replaced.replace("Definitiva", "Ultimate", ignoreCase = true)
        replaced = replaced.replace("Inflige", "Causa", ignoreCase = true)
        replaced = replaced.replace("inflige", "causa", ignoreCase = true)
        replaced = replaced.replace("Aumenta", "Aumenta", ignoreCase = true)
        replaced = replaced.replace("Reduce", "Reduz", ignoreCase = true)
        replaced = replaced.replace("Otorga", "Concede", ignoreCase = true)
        replaced = replaced.replace("otorga", "concede", ignoreCase = true)
        replaced = replaced.replace("Este elemento", "Este item", ignoreCase = true)
        replaced = replaced.replace("Este objeto", "Este item", ignoreCase = true)
        replaced = replaced.replace("este elemento", "este item", ignoreCase = true)
        replaced = replaced.replace("este objeto", "este item", ignoreCase = true)
        replaced = replaced.replace("tu siguiente ataque", "seu próximo ataque", ignoreCase = true)
        replaced = replaced.replace("también se aplica a las torretas", "também se aplica a torres", ignoreCase = true)
        replaced = replaced.replace("creando una onda de choque", "criando uma onda de choque", ignoreCase = true)
        replaced = replaced.replace("a los enemigos detrás del objetivo", "aos inimigos atrás do alvo", ignoreCase = true)
        replaced = replaced.replace("Los campeones a distancia infligen un 75% del daño", "Campeões de ataque à distância causam 75% do dano", ignoreCase = true)
        replaced = replaced.replace("Los campeones a distancia Causan un 75% del daño", "Campeões de ataque à distância causam 75% do dano", ignoreCase = true)
        replaced = replaced.replace("convierte tus ataques básicos en", "transforma seus ataques básicos em", ignoreCase = true)
        replaced = replaced.replace("periódicamente tu próximo golpe se convierte en", "periodicamente seu próximo golpe se torna", ignoreCase = true)
        replaced = replaced.replace("Acelera la eliminación de olas", "Acelera a limpeza de tropas", ignoreCase = true)
        replaced = replaced.replace("agrega daño adicional en las peleas en equipo", "adiciona dano extra em lutas de equipe", ignoreCase = true)
        replaced = replaced.replace("y ayuda a presionar las estructuras cuando se construye adecuadamente.", "e ajuda a pressionar estruturas quando construído adequadamente.", ignoreCase = true)
        replaced = replaced.replace("Es más adecuado para matones cuerpo a cuerpo y tanques que combinan una gran reserva de salud con autos frecuentes", "É mais adequado para lutadores corpo a corpo e tanques que combinam muita vida com ataques básicos frequentes", ignoreCase = true)
        replaced = replaced.replace("ideal para jugadores que desean impactar tanto en intercambios 1 contra 1 como en enfrentamientos prolongados.", "ideal para jogadores que desejam impacto tanto em trocas 1v1 quanto em confrontos prolongados.", ignoreCase = true)
        replaced = replaced.replace("Hender:", "Fender:", ignoreCase = true)
        replaced = replaced.replace("enemigos", "inimigos", ignoreCase = true)
        replaced = replaced.replace("enemigo", "inimigo", ignoreCase = true)
        replaced = replaced.replace("campeones", "campeões", ignoreCase = true)
        replaced = replaced.replace("campeón", "campeão", ignoreCase = true)
        replaced = replaced.replace("torretas", "torres", ignoreCase = true)
        replaced = replaced.replace("torreta", "torre", ignoreCase = true)
    }
    return replaced
}
